package com.eventmgr.web;
import com.eventmgr.util.*;import com.google.gson.JsonObject;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.time.*;import java.util.*;
@WebServlet("/api/org/*") public class OrgServlet extends ApiServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{User u=me(q);String[] s=segs(q);if(s.length==0)throw new ApiError(404,"Not found");if(s[0].equals("events"))send(r,200,Db.query("SELECT e.*, t.price,t.quantity,t.name ticket_name,(SELECT COUNT(*) FROM registrations x WHERE x.event_id=e.id AND x.status<>'CANCELLED') registrations FROM events e LEFT JOIN tickets t ON t.event_id=e.id WHERE e.organizer_id=? ORDER BY e.event_date DESC",u.id));else if(s[0].equals("attendees"))send(r,200,Db.query("SELECT r.id,r.status,r.quantity,r.total,r.created_at,e.id event_id,e.title,e.event_date,t.name ticket_name,u.name attendee_name,u.email attendee_email FROM registrations r JOIN events e ON e.id=r.event_id JOIN tickets t ON t.id=r.ticket_id JOIN users u ON u.id=r.attendee_id WHERE e.organizer_id=? ORDER BY r.created_at DESC",u.id));else if(s[0].equals("updates"))send(r,200,Db.query("SELECT a.*,e.title FROM announcements a JOIN events e ON e.id=a.event_id WHERE a.organizer_id=? ORDER BY a.created_at DESC",u.id));else throw new ApiError(404,"Not found");}
 protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{User u=me(q);String[] s=segs(q);JsonObject b=body(q);if(s.length==1&&s[0].equals("events")){String title=str(b,"title",true),desc=str(b,"description",true),date=str(b,"eventDate",true),time=str(b,"eventTime",true),venue=str(b,"venue",true),cat=str(b,"category",false);LocalDate d;try{d=LocalDate.parse(date);}catch(Exception e){throw new ApiError(400,"Enter a valid event date");}if(d.isBefore(LocalDate.now()))throw new ApiError(400,"Event date cannot be in the past");String status=Settings.bool("require_event_approval",true)?"PENDING":"APPROVED";long eid=Db.insert("INSERT INTO events(organizer_id,title,description,event_date,event_time,venue,category,status) VALUES(?,?,?,?,?,?,?,?)",u.id,title,desc,date,time,venue,cat.isEmpty()?"Community":cat,status);Db.insert("INSERT INTO tickets(event_id,name,price,quantity) VALUES(?,?,?,?)",eid,"General admission",num(b,"price",0,100000),num(b,"quantity",1,100000));Activity.log(u.id,"Event created",title+" was submitted for review");message(r,201,status.equals("PENDING")?"Event submitted for approval":"Event published");}else if(s.length==1&&s[0].equals("updates")){long eid=(long)num(b,"eventId",1,Long.MAX_VALUE);String msg=str(b,"body",true);if(Db.count("SELECT COUNT(*) FROM events WHERE id=? AND organizer_id=?",eid,u.id)==0)throw new ApiError(404,"Event not found");Db.insert("INSERT INTO announcements(event_id,organizer_id,body) VALUES(?,?,?)",eid,u.id,msg);Activity.log(u.id,"Attendee update sent",msg.substring(0,Math.min(msg.length(),120)));message(r,201,"Update sent to registered attendees");}else throw new ApiError(404,"Not found");}
 protected void doPut(HttpServletRequest q,HttpServletResponse r)throws IOException{String[] s=segs(q);User u=me(q);if(s.length!=2||!s[0].equals("events"))throw new ApiError(404,"Not found");long eid=id(s[1]);JsonObject b=body(q);if(Db.count("SELECT COUNT(*) FROM events WHERE id=? AND organizer_id=?",eid,u.id)==0)throw new ApiError(404,"Event not found");Db.update("UPDATE events SET title=?,description=?,event_date=?,event_time=?,venue=?,category=?,status=? WHERE id=? AND organizer_id=?",str(b,"title",true),str(b,"description",true),str(b,"eventDate",true),str(b,"eventTime",true),str(b,"venue",true),str(b,"category",false),Settings.bool("require_event_approval",true)?"PENDING":"APPROVED",eid,u.id);Db.update("UPDATE tickets SET price=?,quantity=? WHERE event_id=?",num(b,"price",0,100000),num(b,"quantity",1,100000),eid);message(r,200,"Event updated");}
 protected void doDelete(HttpServletRequest q,HttpServletResponse r)throws IOException{String[] s=segs(q);User u=me(q);if(s.length!=2||!s[0].equals("events"))throw new ApiError(404,"Not found");long eid=id(s[1]);Map<String,Object> event=Db.one("SELECT title FROM events WHERE id=? AND organizer_id=?",eid,u.id);if(event==null)throw new ApiError(404,"Event not found");Db.update("DELETE FROM events WHERE id=? AND organizer_id=?",eid,u.id);Activity.log(u.id,"Event deleted",(String)event.get("title")+" was removed");message(r,200,"Event deleted");}}
